import sys
sys.path.insert(0, '/home/user/bib/notes/wip/b16-lskc-1b')
from dsl import *
VH = 'vietnam-hanoi'; OP = ['vietnam-operations']
for k, n_ in [('thoi-hoa-ben-cat', 'Thới Hòa'), ('muc-thinh', 'Mục Thịnh'), ('tan-thach', 'Tân Thạch'), ('luong-quoi', 'Lương Quới'), ('cau-nha-thuong', 'Cầu Nhà Thương'), ('binh-chanh-bridge', 'Bình Chánh bridge'), ('chau-phu', 'Châu Phú'), ('ba-lai-river', 'Ba Lai River'), ('hiep-duc', 'Hiệp Đức'), ('ga-lau', 'Ga Lâu'), ('gia-le', 'Gia Lê'), ('cay-dau', 'Cây Dầu'), ('dat-dai', 'Đất Dài'), ('phuoc-tan', 'Phước Tân'), ('an-dan', 'An Dân')]:
    NP(k, n_)
A('1960-02-thoihoa', '1960-02', VH, 'Thủ Dầu Một. In mid-February, as the garrison of the Thới Hòa post, Bến Cát, has just drawn its pay, the commune\'s Party branch with the men inside holds a drinking party, collects the guns and, when the garrison is drunk, kills the oppressors and calls on the rest to give up. Outside the people with the soldiers\' families go to the post to win their men over. The post is taken with all its arms, the commune guards disbanded, the government offices burned and a commune self-defense force built. Thới Hòa is the province\'s spearhead.', 'II, 344', when='Feb., mid', place='thoi-hoa-ben-cat', also=OP, check='the day.')
A('1960-02-tayninh-units', '1960-02', VH, 'Tây Ninh. In early February the province sets up Battalion 14; Châu Thành district sets up Company 40, Gò Dầu and Trảng Bàng Company 33A, Bến Cầu Company 61 and Dương Minh Châu district Company 31A.', 'II, 333', when='Feb., early', place='tay-ninh', also=OP, vis=True, check='the day.')
A('1960-02-cuchi', '1960-02', VH, 'Gia Định. From February many country places of Gia Định rise and take the hamlets. At Củ Chi the district committee orders "all rise together, break up the countryside": with the district\'s armed team the people go into the commune information houses and tear up Diệm\'s portraits, the three-stripe flags and the anticommunist slogans; thousands demonstrate on Routes 7 and 15 with leaflets and banners; the commune and hamlet heads flee. By March the people hold Phú Mỹ Hưng and Nhuận Đức communes, parts of An Nhơn Tây and Trung Lập and the north of Củ Chi.', 'II, 348–49', when='Feb.', place='cu-chi', also=OP, check='the day; the history gives "from February" and the district committee\'s order undated.')
A('1960-02-c13', '1960-02', VH, 'Gia Định. In the same time the Region\'s armed unit C13, working in Củ Chi, Bình Chánh, Nhà Bè, Duyên Hải, Thủ Đức and Dĩ An districts, destroys the An Hòa, Tân Thạnh Tây, Trung Hòa and An Nhơn Tây posts and the Bến Mương restaurant, to back the people\'s rising.', 'II, 348', when='Feb.', place='cu-chi', also=OP, check='the days; the history gives no dates; the place field takes the first district.')
A('1960-01-benthanh', '1960-01', VH, 'Saigon. In January young people of Saigon hang a red flag with the hammer and sickle in the Bến Thành market.', 'II, 349', when='Jan.', place='saigon', also=['vietnam'], tags=['polity:drv'], check='the day; the history gives only the month.')
A('1960-03-muthinh', '1960-03', VH, 'Bình Định. In March four guerrillas of Vân Canh district, who have worked loose the rail with metal pipes and rattan cords, pull a rail out as a Saigon military train reaches Mục Thịnh; the engine runs off the track.', 'II, 354', when='Mar.', place='muc-thinh', also=OP, check='the day; the history\'s sentence breaks off at the engine.')
A('1960-0923-tanthach', '1960-09-23', VH, 'Bến Tre. Sept. 23 Company 261, formed in June, ambushes a Civil Guard platoon at Tân Thạch, Châu Thành, on its way from Mỹ Tho to the town, and destroys it.', 'II, 364', place='tan-thach', also=OP, check='the clock.')
A('1960-0923-luongquoi', '1960-09-23', VH, 'Bến Tre. Sept. 23 a platoon of Giồng Trôm district\'s armed force destroys a Civil Guard platoon at Lương Quới, on its way from Giồng Trôm to the town.', 'II, 364', place='luong-quoi', also=OP, check='the clock.')
A('1960-0923-nhathuong', '1960-09-23', VH, 'Bến Tre. The night of Sept. 23 the town\'s self-defense destroys the Self-Defense post at the Nhà Thương bridge and takes the arms of the guard at the Cái Cối bridge. The town had been empty and the shops shut that day on a rumor that the Viet Cong would attack in force.', 'II, 364', place='cau-nha-thuong', band_='night', also=OP, check='the hour.')
A('1960-0924-binhchanh', '1960-09-24', VH, 'Bến Tre. The afternoon of Sept. 24, after Saigon has pulled two battalions out of Giồng Trôm into the town, the people of Lương Hòa, Long Mỹ and Bình Hòa communes float coconut-trunk rafts with explosive down the stream and bring down the Bình Chánh bridge, cutting the road from the town to Giồng Trôm.', 'II, 364', place='binh-chanh-bridge', band_='afternoon', also=OP)
A('1960-0924-chauphu', '1960-09-24', VH, 'Bến Tre. Sept. 24 in Châu Phú commune, Giồng Trôm, Chống, commander of the Civil Guard company and a man of the Party inside, gathers his company to collect their guns for inspection; a squad of Company 261 in Civil Guard dress walks into the post and takes the arms as the soldiers are called on to give up; the people raze the post. Another party takes the Nhà Thờ post by lam taxi without a shot.', 'II, 364', place='chau-phu', also=OP, check='the hour; the history places it with the rising at 5 p.m. of Sept. 24.')
A('1960-0924-balai', '1960-09-24', VH, 'Bến Tre. About Sept. 24 the communes of Phong Nẫm, Phong Mỹ, Châu Bình and Châu Hòa, with the armed force and men inside, force the surrender and raze the posts along the Ba Lai river: a large free area, 100 weapons and over 100 prisoners taken. Over the night of Sept. 24 hundreds of thousands in nearly 100 communes beat drums and clappers, burn torches and march round the posts; 20 posts of Giồng Trôm give up their arms, 10 of Ba Tri are destroyed or surrender, and dozens in Châu Thành, Bình Đại and Thạnh Phú.', 'II, 365', place='ba-lai-river', band_='night', also=OP, check='the day; the history gives "the same time" as the Châu Phú fight of Sept. 24.')
A('1960-1003-mocay', '1960-10-03', VH, 'Bến Tre. Oct. 3 the province sends Company 261 from Giồng Trôm to help in Mỏ Cày, where Saigon holds firm. Over the Hàm Luông with men inside it takes the Cái Quao post and frees An Định commune, goes on to Hương Mỹ; the Self-Defense men of the Tân Trung post flee; Minh Đức post is besieged and surrenders. In north Mỏ Cày the district\'s platoon forces the Thanh Tân and Tân Phú Tây posts and isolates Cái Mơn; a series of communes, Catholic ones too, rise.', 'II, 365', place='ben-tre', also=OP, check='the day of each post; the history gives Oct. 3 for the move.')
A('1960-0920-hiepduc', '1960-09-20', VH, 'Quảng Nam. Sept. 20 the province\'s armed force with the district\'s armed work team attacks the Hiệp Đức district seat: a Civil Guard company destroyed, all its arms taken.', 'II, 377', place='hiep-duc', also=OP)
A('1960-09-kysanh', '1960-09', VH, 'Quảng Nam. In September, backed by the Tam Kỳ district\'s armed work team, the people of Kỳ Sanh commune rise, kill the oppressors and free Tú Mỹ hamlet, the first in the province\'s plain.', 'II, 377', when='Sept.', place='ky-sanh', also=OP, check='the day.')
A('1960-09-galau', '1960-09', VH, 'Quảng Nam. In September, the province\'s new companies H29 and H30 with the Region\'s armed forces attack the Ga Lâu post (Hiên) and the Sáu post (Giằng) and destroy four platoons, taking many arms.', 'II, 377', when='Sept.', place='quang-nam', also=OP, check='the day.')
A('1960-11-dabana', '1960-11', 'vietnam', 'Bình Định. In November Saigon sweeps Đá Bàn, An Lão district, and kills 32 villagers.', 'II, 379', when='Nov.', place='an-lao', also=['vietnam-hanoi'], tags=['polity:rvn'], check='the day; the figure is the history\'s.')
A('1960-12-andan', '1960-12', 'vietnam', 'Bình Định. At the end of December a Saigon battalion of Rhade troops under Đinh Ngô, brought from Quảng Ngãi, sweeps, robs and burns the communes of An Dân, An Lạc and An Vinh, An Lão district.', 'II, 379', when='Dec., late', place='an-lao', also=['vietnam-hanoi'], tags=['polity:rvn'], check='the day.')
A('1960-12-datdai', '1960-12', VH, 'Bình Định. After the Rhade battalion\'s sweep Unit 2/9 ambushes at Đất Dài and destroys a squad, forcing it to withdraw; the people then break up the Gò Nĩ concentration camp and free the area west of the An Lão river.', 'II, 379–80', when='Dec., late', place='dat-dai', also=OP, check='the day.')
A('1960-06-binhdinh-congress', '1960-06', VH, 'Bình Định. The provincial Party congress, June, resolves that armed struggle shall back the political movement of the masses more strongly.', 'II, 379 n.1', when='June', place='binh-dinh', also=OP, vis=True, check='the day; the resolution is cited from the Bình Định Party History Board\'s archive.')
A('1960-06-co261', '1960-06', VH, 'Bến Tre. Company 261 of the province\'s armed force is formed in June.', 'II, 364 n.1', when='June', place='ben-tre', also=OP, vis=True, check='the day.')
A('1960-11-giale', '1960-11', VH, 'Khánh Hòa. In November the province\'s armed force destroys the Gia Lê post and 5,000 people of the Bố Lạng, Gia Lê and Thác Trại zones rise and break the controls. In the same month the Cây Dầu post zone is broken and the areas of Tà Lương and Suối Hai are freed.', 'II, 375', when='Nov.', place='gia-le', also=OP, check='the days; two acts, the history gives them in one passage without days.')
A('1960-11-phuyen', '1960-11', VH, 'Phú Yên. In November the province\'s armed force opens a campaign to free the highlands of Sơn Hòa district. The armed work teams back the people of Phước Tân commune, who kill the oppressors, end Saigon\'s rule and set up a self-government board; Quang Hiển, Tân Vinh, Phước Thuận, Đá Mài and Phú Mỡ follow. By the end of the year the west of the district is held, 13,000 people free.', 'II, 380–81', when='Nov.', place='phuoc-tan', also=OP, tags=['ok:fields-at'], check='the days.')
